function fillExitDistances(rooms: number[][]): void {
  const R = rooms.length, C = rooms[0].length;
  for (let er = 0; er < R; er++) {
    for (let ec = 0; ec < C; ec++) {
      if (rooms[er][ec] !== 0) continue;
      const seen = Array.from({ length: R }, () => new Array(C).fill(false));
      seen[er][ec] = true;
      let level = [[er, ec]], d = 0;
      while (level.length) {
        d++;
        const next: number[][] = [];
        for (const [r, c] of level)
          for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
            if (nr < 0 || nc < 0 || nr >= R || nc >= C || seen[nr][nc] || rooms[nr][nc] <= 0) continue;
            seen[nr][nc] = true;
            rooms[nr][nc] = Math.min(rooms[nr][nc], d);
            next.push([nr, nc]);
          }
        level = next;
      }
    }
  }
}

