function fillExitDistances(rooms: number[][]): void {
  const FAR = 2147483647, R = rooms.length, C = rooms[0].length;
  const queue: number[][] = [];
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (rooms[r][c] === 0) queue.push([r, c]);
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (nr >= 0 && nc >= 0 && nr < R && nc < C && rooms[nr][nc] === FAR) {
        rooms[nr][nc] = rooms[r][c] + 1; // first visit is the shortest
        queue.push([nr, nc]);
      }
    }
  }
}

